import{scope,visibleView}from'./common.mjs';import{MAPS,prepareS4TargetSupport,borrowSupport}from'./support.mjs';import{GYM4_ASSET_MANIFEST_SHA}from'../gohyeon-gym4/asset-pins.mjs';import{createGym4Renderer}from'./gym-renderer.mjs';
const assetModuleURL=import.meta.url;const base=new URL('../gohyeon-gym4/',assetModuleURL);if(!base.pathname.endsWith('/'))base.pathname+='/';const json=b=>JSON.parse(new TextDecoder().decode(b));
export async function prepareS4GymPresentation(options={}){const{mapId=MAPS.gym,appearance='boy',canvasFactory=(w,h)=>new OffscreenCanvas(w,h)}=options;if(mapId!==MAPS.gym||!['boy','girl'].includes(appearance))throw Error('S4_GYM_SELECTION');const td=Object.getOwnPropertyDescriptor(options,'supportLeaseToken');if(td&&(!td.enumerable||!Object.hasOwn(td,'value'))||!td&&'supportLeaseToken'in options)throw Error('S4_SUPPORT_TOKEN_DESCRIPTOR');const s=scope(options),canvases=[],make=(w,h)=>{s.check();const c=canvasFactory(w,h);canvases.push(c);return c};let support,renderer,drawPlayer;s.onCleanup(()=>support?.dispose());s.onCleanup(()=>{try{renderer?.dispose()}finally{renderer=null;drawPlayer=null}});s.onCleanup(()=>{for(const c of canvases)try{c.width=c.height=1}catch{}canvases.length=0});try{s.check();support=td?.value==null?await prepareS4TargetSupport({...options,mapId}):borrowSupport(td.value,mapId);s.check();const pins=json(await s.pinned(new URL('ASSET_PINS.json',base),GYM4_ASSET_MANIFEST_SHA)),inputs={};for(const key of['image04','image05','leader','sub01','sub02','doorLayers',...(appearance==='boy'?['player']:[])]){const p=pins[key],b=await s.pinned(new URL(p.path,base),p.sha256,p.bytes);inputs[key]=p.kind==='image'?await s.image(b,...p.dimensions):json(b)}if(appearance==='girl'){const a=new URL('../../assets/approved-atlases/',base),m=json(await s.pinned(new URL('manifest.json',a),'3f337223b51724f825810ff0a15a6eecbb02897a1202f836342f35a9272ff4cc')),p=m.atlases['player/PLAYER_FEMALE'];const atlas=await s.image(await s.pinned(new URL('../../'+p.src,base),p.sha256),p.width,p.height);drawPlayer=(ctx,foot,frame)=>{const f=m.frames.player['PLAYER_FEMALE.'+['FRONT','RIGHT','LEFT','BACK'][Math.floor(frame/3)]+'.'+['IDLE','A','B'][frame%3]];if(!f||f.atlas!=='player/PLAYER_FEMALE')throw Error('GYM4_GIRL_FRAME');const scale=80/192;ctx.drawImage(atlas,...f.rect,foot[0]-f.anchor[0]*scale,foot[1]-f.anchor[1]*scale,f.width*scale,f.height*scale)}}renderer=createGym4Renderer({inputs,canvasFactory:make,drawPlayer});s.check();return visibleView({s,support,appearance,make,gym:true,drawNative:(ctx,v)=>renderer.draw(ctx,{state:v.pose.state,foot:v.pose.foot,facing:v.pose.facing,walking:v.walking},v.clock)})}catch(e){s.dispose();throw e}}
